import java.util.LinkedHashSet;
import java.util.Set;

public class GameOfLife {

    private static final int MIN_NEIGHBOURS_TO_SURVIVE = 2;
    private static final int MAX_NEIGHBOURS_TO_SURVIVE = 3;

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        Set<Cell> next = new LinkedHashSet<>();
        for (Cell cell : livingCells) {
            if (survives(countLivingNeighbours(cell, livingCells))) {
                next.add(cell);
            }
        }
        return next;
    }

    private boolean survives(int livingNeighbours) {
        return livingNeighbours >= MIN_NEIGHBOURS_TO_SURVIVE
                && livingNeighbours <= MAX_NEIGHBOURS_TO_SURVIVE;
    }

    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (Cell neighbour : cell.neighbours()) {
            if (livingCells.contains(neighbour)) {
                count++;
            }
        }
        return count;
    }
}
